export type StoreLocale = "id" | "en";

export const LOCALE_COOKIE = "ultrastore_locale";

export function parseLocale(value: string | undefined): StoreLocale {
  return value === "en" ? "en" : "id";
}

// Store copy is written for each language, not generated by machine translation.
export function copy(locale: StoreLocale, id: string, en: string): string {
  return locale === "en" ? en : id;
}

export function formatRupiah(value: number, locale: StoreLocale): string {
  return new Intl.NumberFormat(locale === "en" ? "en-US" : "id-ID", {
    style: "currency",
    currency: "IDR",
    maximumFractionDigits: 0,
  }).format(value);
}
